# the probe entry generator
sub('''def probe_entry(rng, h, probe_rate=0.7):
    """the adapter's [lead, applied, evaluations, probe_worlds, margin, chosen] for one exploiter dhist entry (a search record): a probe on
    probe_rate of the leads at max hand > 7, margin uniform on [-0.5, 0.4] (applied iff > 0), chosen on about half the entries"""
    lead = h[9]
    if not lead or h[8] <= 7 or rng.random() >= probe_rate:
        return [lead, False, None, None, None, False]
    margin = round(rng.uniform(-0.5, 0.4), 4) or 0.0001
    applied = margin > 0
    return [lead, applied, 8 * rng.randint(10, 30), 8, margin, applied and rng.random() < 0.5]
''', '''def probe_entry(rng, h, ncards, probe_rate=0.7):
    """the adapter's [lead, applied, evaluations, probe_worlds, margin, chosen, added_kind, pool, played_kind] for one exploiter dhist entry
    (a search record): played_kind from the trace's card count on a lead (None on a follow); on a lead at max hand > 7 a pool
    [singles, pairs, tractors] on probe_rate of them (None otherwise: fewer than two admitted slots), a probe when the pool is non-empty
    with margin uniform on [-0.5, 0.4] (applied iff > 0; the added kind drawn from the pool's non-empty kinds), chosen on about half the
    entries whose added kind is the played kind"""
    lead = h[9]
    if not lead:
        return [False, False, None, None, None, False, None, None, None]
    pk = KIND_OF[ncards]
    if h[8] <= 7 or rng.random() >= probe_rate:
        return [True, False, None, None, None, False, None, None, pk]
    pool = [rng.randint(0, 20), rng.randint(0, 4), rng.randint(0, 1)]
    if sum(pool) == 0:
        return [True, False, None, None, None, False, None, pool, pk]
    margin = round(rng.uniform(-0.5, 0.4), 4) or 0.0001
    applied = margin > 0
    offered = [k for k, x in zip(KINDS, pool) if x > 0]
    kind = (pk if pk in offered and rng.random() < 0.6 else rng.choice(offered)) if applied else None
    chosen = applied and kind == pk and rng.random() < 0.7
    return [True, applied, 8 * rng.randint(10, 30), 8, margin, chosen, kind, pool, pk]
''')
